		temp_switch(savedbuf, 0);
	else if (savedbuf < xbufcur) {
		bufs_switchwft(savedbuf)
	}
	free(archive);
	free(original);
	free(task);
	return ret;
}

/* Run the apack task without a prompt. The live conversation stays detached
