+        }
+        { print }
+    ' README > "$tmp" &&
+    awk -f exspec.awk "$tmp" > "$tmp.h" &&
+    mv -f "$tmp.h" exspec.h
+    ret=$?
+    rm -f "$tmp" "$tmp.h"
+    return "$ret"
+}
